package i18n
import("testing";"os";"path/filepath";"sync";"sync/atomic";"golang.org/x/sys/unix")
func TestReviewReferenceLifecycle(t *testing.T){d:=t.TempDir();cur:=filepath.Join(d,"a");p:=&PrefStore{Root:func()string{return cur}};_,a:=p.root();fd:=a.h;if e:=p.Close();e!=nil{t.Fatal(e)};if a.closed{t.Fatal("closed active root")};var st unix.Stat_t;if e:=unix.Fstat(fd,&st);e!=nil{t.Fatal("in-flight fd invalid",e)};p.release(a);if !a.closed{t.Fatal("not closed at final release")};if e:=unix.Fstat(fd,&st);e!=unix.EBADF{t.Fatal("fd not closed",e)};f,e:=os.Open(d);if e!=nil{t.Fatal(e)};defer f.Close();p.Close();if _,e=f.Stat();e!=nil{t.Fatal("Close double-closed reused fd",e)};if e=p.Set("en");e!=nil{t.Fatal("post-Close reopen failed",e)};if p.Get()!="en"{t.Fatal("reopened value")};p.Close()}
func TestReviewConcurrentRootClose(t *testing.T){d:=t.TempDir();var n atomic.Uint64;p:=&PrefStore{Root:func()string{if n.Add(1)%2==0{return filepath.Join(d,"a")};return filepath.Join(d,"b")}};var wg sync.WaitGroup;for g:=0;g<8;g++{wg.Add(1);go func(){defer wg.Done();for i:=0;i<50;i++{if e:=p.Set("en");e!=nil{t.Error(e)};_ = p.Get();if i%5==0{p.Close()}}}()};wg.Wait();p.Close()}
